// Builds the share viewer (browser JavaScript and CSS) into experiences/sharing/viewer-bundle.generated.ts, which the
// plugin embeds in every shared HTML file. Run by `npm run build` before tsc; the generated file is committed and
// `npm run verify` checks it is current (the same way as main.js and compiled.json).
import { build } from "esbuild";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format, resolveConfig } from "prettier";
import { composeViewerCss } from "./viewer-css.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const output = path.join(root, "experiences/sharing/viewer-bundle.generated.ts");

const bundle = await build({
  entryPoints: [path.join(root, "experiences/sharing/viewer/index.ts")],
  bundle: true,
  write: false,
  format: "iife",
  target: "es2019",
  platform: "browser",
  minify: true,
  legalComments: "none",
  logLevel: "warning"
});
const js = bundle.outputFiles[0].text.trim();
// The script is placed inside <script>…</script>: neither sequence may appear in it.
if (/<\/script|<!--/i.test(js)) throw new Error("The viewer bundle contains a sequence that would end its <script> block.");

const css = composeViewerCss(
  readFileSync(path.join(root, "experiences/sharing/viewer/viewer.css"), "utf8"),
  readFileSync(path.join(root, "styles.css"), "utf8")
);

const source = `// GENERATED by scripts/build-viewer.mjs from experiences/sharing/viewer/* and styles.css. Do not edit.
/** The share viewer program (one IIFE, no external requests). */
export const SHARE_VIEWER_JS = ${JSON.stringify(js)};
/** The share viewer stylesheet: base tokens, the card, canvas and panel rules from styles.css, then viewer-only rules. */
export const SHARE_VIEWER_CSS = ${JSON.stringify(css)};
`;
const options = (await resolveConfig(output)) ?? {};
writeFileSync(output, await format(source, { ...options, parser: "typescript" }));
process.stdout.write(`share viewer: ${js.length} bytes of JavaScript, ${css.length} bytes of CSS\n`);
